-- Ourgument: the example arguments (Should the death penalty be abolished? / Is it wrong to raise animals for meat? / Should every adult get a basic income?)
-- as real public posts, authored by a "Claude" account, so the public system has
-- something in it from the start. Written by reasonance/tools/seed-examples.mjs.
--
-- The Claude account is a plain row with no email, phone or password and is
-- banned from signing in, so nobody can use it; it only signs these posts.
-- A post someone already made with the same words is reused, not copied.
-- Safe to run more than once. If anything goes wrong, it skips seeding with a
-- warning rather than stopping later migrations.

create or replace function pg_temp.rs_seed(who uuid, pid uuid, k text, ty text, tx text, fa text, a uuid, b uuid, pr text)
returns uuid language plpgsql as $$
declare got uuid;
begin
  if exists (select 1 from public.rs_posts where id = pid) then return pid; end if;
  if not (k = 'node' and ty = 'combiner') then
    got := public.rs_find(k, ty, tx, fa, a, b);
    if got is not null then return got; end if;
  end if;
  values (pid, who, k, ty, coalesce(tx, ''), fa, a, b, pr);
  return pid;
end $$;

create temp table if not exists seed_posts (item text primary key, post uuid);

do $$
declare
  claude uuid := 'fd755006-5431-4848-b134-17805336f581';
  keep uuid[] := array['a387aca2-aca5-498e-ade0-957548d4b362', 'f877b57e-537c-4f9d-9dc5-87874eebd922', '4f3dc63e-6b47-4d55-b555-406a660deebb', '6ae37d84-593f-4d1e-9a77-58649affbd22', 'f11255dd-d490-4c14-a9a9-7f012c3dd148', '7fa92163-184b-4fe1-8071-a920cbbca6a9', '63584e4b-c9ed-4ab9-bb90-aee8d8514d12', 'c54df275-3ca2-47ca-8fb9-b8e236ab6cae', 'b288fe44-c952-4293-a8e5-55f50f1a8e9a', '404ed6de-e3c5-4090-9484-4ae061adea4c', '31b9e272-d2b8-40d8-b565-1681489ed717', 'dba95ca3-4d87-4529-a5f2-1c8a136e63c8', '23c43722-ed7c-4c35-93ae-b75d78057c4a', 'c1596474-1d41-4c16-944f-2444a07db8dd', 'ca8c2808-779b-486b-a630-bf7ad1f12dd2', '50ede3b0-9e97-4354-980c-f39b6b5ed4eb', 'a299e660-bc4a-4cf2-bd63-6ce3a5bdd14f', '25f5c91c-06b8-4cc6-a06d-ecceb9230702', '596f9e32-5544-4ba0-8490-2be61c40ca08', '5cc15c01-ed20-4428-bf24-e7b6c58f2093', 'a6969fcc-e5b1-4b27-b7b6-97f6cb72715a', '36d4e895-cc5f-4ac5-9bb8-f09f04fbb516', '56b016e2-3634-4cf2-90d6-8127e43100b6', '4330f04b-8f64-4812-84b4-f78500910ad2', '5f331fc6-b37a-46b9-8ee9-36ccb963235f', 'fd25ca54-5d6b-4bf2-bff8-a414b8241160', 'eec44511-0e4e-4eb5-9cf0-d6aec7885c90', '88fcdc16-fefb-419b-b45a-f8048e7c4f8a', 'd21fdba3-d6f8-41df-aede-71506405f4d7', '9da7860e-d551-419b-a713-750dc617e66f', '2eaa1a4d-4604-4018-8f7c-17f40fd77426', 'e48e940f-3ae3-40d2-9a1a-e399abc1825c', 'b4e621a7-2d60-444c-8eb2-33f585c988e0', '48e0ed1a-a87f-4178-8317-cd7094d6dfaf', '2b76b1db-70dd-44c1-96c6-7af9ce9de1aa', 'c2364950-1ce4-428b-aaad-203f87dd3d6a', '572d681b-16f8-4615-a118-f365401c451d', '1c9a9d17-3793-440b-bb11-688224ea6a91', '8d5acdea-65fb-4e36-8680-adb48bb7380f', 'c476df32-c156-41f7-ad75-cda040e32e9e', '0ed9cac0-494a-4e9e-b7c8-fa68d6163b91', 'cf5a7ba7-3039-4cc1-adb3-82a71db4a4d0', '2172289e-7e76-4ccd-8b22-718a158a8b50', '39297a9a-87db-4874-8ec5-5576e0d37f40', '13df20c7-93ac-4911-8f56-a84902c9f8f8', '3c3b2add-a97e-4f9e-b1ca-6ece3757faca', '3df379ef-41a2-4dbf-a218-b0297109e55c', '3112f062-08e2-46e8-8e5e-a234ee2351db', '788f67a1-95bf-42d4-a997-ce5dcd894439', '0eab45e9-b295-4e17-91d6-256c6b1ad1ac', '615c9caa-7633-496d-b732-1660e9e4460a', '157ceddc-3bc3-4fd2-85b8-b1d82fef253d', '40d0f631-7596-406e-9385-07fb86b09dd2', '47b37afe-54d1-41e3-93a4-4be6555cd6be', '9fa0b61b-5b14-458d-8e31-c7d33f53674b', '56d35b9d-765c-44a6-bf69-5cef4f8ebeaa', '8cb64685-6be5-4b96-a13f-fbb45efc7881', '01dc10f1-e477-417e-a71a-63200be3d981', '2f18105a-8e66-46fa-98c5-12b725f1d1fb', 'e6916f9f-0e48-42bf-ab76-893487ca2771', '7af9dcc2-d1c5-4785-9a9b-878dd5ed34ea', '2f738a41-5ec8-4335-af30-3064f62ec8b4', '3a8a2ffe-ef8c-436b-addf-854d7ea85cba', '64ff0c32-366b-46d8-ac98-6c1d9cd75312', '9e5a262d-443e-4a97-9312-a50426daa70d', '1d59602e-a9a9-4d9a-b070-95d936239ac1', '56ae62bf-c2d0-48bc-9379-121476e5f200', '5c5fe81a-e1e8-43e8-90b1-b33fefe68432', '2b19dfe3-bf37-4d25-b7b4-7189cc16a134', '3b06a631-15b4-4cda-a65f-75f38dfe5aac', '03885899-5beb-4e78-9a6f-d058a90a0b71', '60b36114-bea2-404f-b876-6076d66e0455', '09f7bf8a-a587-4e05-993a-fe3deff1af95', 'bbc9511d-dae0-43c7-b4f0-3e677ad27aa9', '8e6b133f-7dec-4c49-a5ac-cd2444b379e3', 'efe9c5e0-03ea-4582-a37d-fba1a93d3126', 'dda48930-3dbf-46a9-a6f7-c5a2b211c504']::uuid[];
begin
  if not exists (select 1 from auth.users where id = claude) then
    values (claude, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
      '{"provider":"none","note":"Signs the example posts. Cannot sign in."}', '{}', now(), now(), 'infinity');
  end if;
  if not exists (select 1 from public.profiles where id = claude) then
    values (claude, case when exists (select 1 from public.profiles where lower(username) = 'claude') then 'Claude_AI' else 'Claude' end);
  end if;

  -- Remove Claude's older examples, keeping any post someone else rated or
  -- built an arrow on, so nobody's views or arguments lose their footing.
  loop
    delete from public.rs_posts p
    where p.author = claude
      and p.id <> all (keep)
      and not exists (select 1 from public.rs_ratings r where r.post_id = p.id and r.user_id <> claude)
      and not exists (select 1 from public.rs_posts o where o.from_post = p.id or o.to_post = p.id);
    exit when not found;
  end loop;

  -- Should the death penalty be abolished?
  -- Is it wrong to raise animals for meat?
  -- Should every adult get a basic income?
exception when others then
  raise warning 'Ourgument examples were not posted: %', sqlerrm;
end $$;
